/bin/zsh -lc "python3 -c 'import random
for r in range(2,9):
 longest=0; unresolved=0; example=None
 for trial in range(100):
  c=[random.randrange(30) for _ in range(r)]; b=random.randrange(r); seen={}
  for t in range(5000):
   mi=min(c); state=(b,tuple(x-mi for x in c))
   if state in seen:
    longest=max(longest,t); break
   seen[state]=t
   c[b]+=1
   b=sum(x>=c[b] for x in c)-1
  else:
   unresolved+=1; example=(c,b)
 print(r,longest,unresolved,example)'"

